<?php
declare(strict_types=1);require_once dirname(__DIR__).'/includes/auth.php';require_once __DIR__.'/layout.php';require_once dirname(__DIR__).'/services/student_portal.php';$current=tuman_require_role('STUDENT');$db=tuman_database();$assignments=tuman_student_teacher_assignments($db,$current['id']);try{$assignmentId=tuman_student_owned_assignment_id($db,$current['id'],$_GET['assignment_id']??null);$invoices=tuman_student_invoices($db,$current['id'],$assignmentId);}catch(InvalidArgumentException $e){http_response_code(404);exit('Invoices unavailable.');}tuman_student_page_start('My invoices');
?>
<h1>My invoices</h1><form method="get"><p><label>Teacher <select name="assignment_id"><option value="">All my Teachers</option><?php foreach($assignments as $assignment): ?><option value="<?= (int)$assignment['assignment_id'] ?>"<?= $assignmentId===(int)$assignment['assignment_id']?' selected':'' ?>><?= htmlspecialchars(trim($assignment['first_name'].' '.($assignment['last_name']??'')),ENT_QUOTES,'UTF-8') ?></option><?php endforeach; ?></select></label></p><p><button>View</button></p></form><div style="overflow-x:auto"><table><thead><tr><th>Teacher</th><th>Invoice</th><th>Period</th><th>Total</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($invoices as $invoice): ?><tr><td><?= htmlspecialchars(trim($invoice['teacher_first_name'].' '.($invoice['teacher_last_name']??'')),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($invoice['invoice_number'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($invoice['billing_period_from'].' to '.$invoice['billing_period_to'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars(tuman_invoice_money_label($invoice['total_amount'],$invoice['currency_code']),ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($invoice['status'],ENT_QUOTES,'UTF-8') ?></td><td><a href="/Tuman/student/invoice-view.php?id=<?= (int)$invoice['id'] ?>">View</a></td></tr><?php endforeach; ?></tbody></table></div><?php if($invoices===[]): ?><p>No invoices are available.</p><?php endif; ?><?php tuman_student_page_end(); ?>
